/**
 * Web Push for staff phones (Android, desktop, and iPhone when the app is added to the home screen).
 * The VAPID signing key is generated by the server on first use and stored encrypted in app_secrets.
 */
import webpush from "web-push";
import type { SupabaseClient } from "@supabase/supabase-js";
import { serverEnv } from "../env";

export type PushPayload = { title: string; body: string; url?: string; tag?: string };
type Sealed = { v: 1; iv: string; data: string };
const VAPID = "web_push_vapid";
const encoder = new TextEncoder();
const toBase64 = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes));
const fromBase64 = (value: string) => Uint8Array.from(atob(value), (char) => char.charCodeAt(0));

async function key(secret?: string) {
  const material = secret ?? serverEnv().SUPABASE_SERVICE_ROLE_KEY;
  if (!material) throw new Error("ENCRYPTION_KEY_MISSING");
  const digest = await crypto.subtle.digest("SHA-256", encoder.encode(`cliniq-secret-v1:${material}`));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, ["encrypt", "decrypt"]);
}
export async function sealText(value: string, secret?: string): Promise<Sealed> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const data = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, await key(secret), encoder.encode(value)));
  return { v: 1, iv: toBase64(iv), data: toBase64(data) };
}
export async function openText(sealed: unknown, secret?: string) {
  const value = sealed as Partial<Sealed> | null;
  if (!value || value.v !== 1 || !value.iv || !value.data) return null;
  try { return new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: fromBase64(value.iv) }, await key(secret), fromBase64(value.data))); } catch { return null; }
}

/** The public key browsers need, and the private key the server signs with. Created once. */
export async function vapidKeys(db: SupabaseClient) {
  const read = async () => {
    const { data } = await db.from("app_secrets").select("sealed,public_value").eq("name", VAPID).maybeSingle();
    const row = data as { sealed: unknown; public_value: string | null } | null;
    const privateKey = row ? await openText(row.sealed) : null;
    return row?.public_value && privateKey ? { publicKey: row.public_value, privateKey } : null;
  };
  const existing = await read();
  if (existing) return existing;
  const fresh = webpush.generateVAPIDKeys();
  await db.from("app_secrets").upsert({ name: VAPID, sealed: await sealText(fresh.privateKey), public_value: fresh.publicKey }, { onConflict: "name", ignoreDuplicates: true });
  const stored = await read();
  if (!stored) throw new Error("VAPID_UNAVAILABLE");
  return stored;
}

/** Sends one notification to every phone of the given people. Gone subscriptions are removed. */
export async function pushToStaff(db: SupabaseClient, organisationId: string, staffIds: string[], payload: PushPayload | ((staffId: string) => PushPayload), subject = "https://nightprofit-two.vercel.app") {
  const reached = new Set<string>();
  if (!staffIds.length) return reached;
  const { data } = await db.from("push_subscriptions").select("id,staff_id,endpoint,p256dh,auth,failure_count").eq("organisation_id", organisationId).in("staff_id", [...new Set(staffIds)]);
  const rows = (data ?? []) as { id: string; staff_id: string; endpoint: string; p256dh: string; auth: string; failure_count: number }[];
  if (!rows.length) return reached;
  const keys = await vapidKeys(db);
  await Promise.all(rows.map(async (row) => {
    const message = typeof payload === "function" ? payload(row.staff_id) : payload;
    try {
      await webpush.sendNotification({ endpoint: row.endpoint, keys: { p256dh: row.p256dh, auth: row.auth } }, JSON.stringify(message), { vapidDetails: { subject, publicKey: keys.publicKey, privateKey: keys.privateKey }, TTL: 6 * 3600, urgency: "high" });
      reached.add(row.staff_id);
      await db.from("push_subscriptions").update({ last_success_at: new Date().toISOString(), failure_count: 0 }).eq("id", row.id);
    } catch (error) {
      const status = (error as { statusCode?: number }).statusCode;
      if (status === 404 || status === 410 || row.failure_count >= 4) await db.from("push_subscriptions").delete().eq("id", row.id);
      else await db.from("push_subscriptions").update({ failure_count: row.failure_count + 1 }).eq("id", row.id);
    }
  }));
  return reached;
}
